        // Surah 97
        97 to listOf(
            Ayah(97, 1, "بِّسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ ۝1", "Verse 1", "إنا أنزلنا القرآن في ليلة الشرف والفضل، وهي إحدى ليالي شهر رمضان.", "", 598, 30),
            Ayah(97, 2, "وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ ۝2", "Verse 2", "وما أدراك -أيها النبي- ما ليلة القدر والشرف؟", "", 598, 30),
            Ayah(97, 3, "لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ ۝3", "Verse 3", "ليلة القدر ليلة مباركة، فَضْلُها خير من فضل ألف شهر ليس فيها ليلة قدر.", "", 598, 30),
            Ayah(97, 4, "تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ ۝4", "Verse 4", "يكثر نزول الملائكة وجبريل عليه السلام فيها، بإذن ربهم من كل أمر قضاه في تلك السنة.", "", 598, 30),
            Ayah(97, 5, "سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ ۝5", "Verse 5", "هي أمن كلها، لا شرَّ فيها إلى مطلع الفجر.", "", 598, 30),
        ),
        // Surah 98
        98 to listOf(
            Ayah(98, 1, "لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ ۝1", "Verse 1", "لم يكن الذين كفروا من اليهود والنصارى والمشركين تاركين كفرهم حتى تأتيهم العلامة التي وُعِدوا بها في الكتب السابقة.", "", 598, 30),
            Ayah(98, 2, "رَسُولٌۭ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًۭا مُّطَهَّرَةًۭ ۝2", "Verse 2", "وهي رسول الله محمد صلى الله عليه وسلم، يتلو قرآنًا في صحف مطهرة.", "", 598, 30),
            Ayah(98, 3, "فِيهَا كُتُبٌۭ قَيِّمَةٌۭ ۝3", "Verse 3", "في تلك الصحف أخبار صادقة وأوامر عادلة، تهدي إلى الحق وإلى صراط مستقيم.", "", 598, 30),
            Ayah(98, 4, "وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ ۝4", "Verse 4", "وما اختلف الذين أوتوا الكتاب من اليهود والنصارى في كون محمد صلى الله عليه وسلم رسولا حقًا؛ لما يجدونه من نعته في كتابهم، إلا مِن بعد ما تبينوا أنه النبي الذي وُعِدوا به في التوراة والإنجيل، فكانوا مجتمعين على صحة نبوته، فلما بُعِث جحدوها وتفرَّقوا.", "", 598, 30),
            Ayah(98, 5, "وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ ۝5", "Verse 5", "وما أمروا في سائر الشرائع إلا ليعبدوا الله وحده قاصدين بعبادتهم وجهه، مائلين عن الشرك إلى الإيمان، ويقيموا الصلاة، ويُؤَدُّوا الزكاة، وذلك هو دين الاستقامة، وهو الإسلام.", "", 598, 30),
            Ayah(98, 6, "إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ ۚ أُو۟لَٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ ۝6", "Verse 6", "إن الذين كفروا من اليهود والنصارى والمشركين عقابهم نار جهنم خالدين فيها، أولئك هم أشد الخليقة شرا.", "", 598, 30),
            Ayah(98, 7, "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ ۝7", "Verse 7", "إن الذين صَدَّقوا الله واتبعوا رسوله وعملوا الصالحات، أولئك هم خير الخلق.", "", 598, 30),
            Ayah(98, 8, "جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ ۝8", "Verse 8", "جزاؤهم عند ربهم يوم القيامة جنات إقامة واستقرار في منتهى الحسن، تجري من تحت قصورها الأنهار، خالدين فيها أبدًا، رضي الله عنهم فقبل أعمالهم الصالحة، ورضوا عنه بما أعدَّ لهم من أنواع الكرامات، ذلك الجزاء الحسن لمن خاف الله واجتنب معاصيه.", "", 599, 30),
        ),
        // Surah 99
        99 to listOf(
            Ayah(99, 1, "إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا ۝1", "Verse 1", "إذا رُجَّت الأرض رجًّا شديدًا، وأخرجت ما في بطنها من موتى وكنوز، وتساءل الإنسان فزعًا: ما الذي حدث لها؟", "", 599, 30),
            Ayah(99, 2, "وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا ۝2", "Verse 2", "إذا رُجَّت الأرض رجًّا شديدًا، وأخرجت ما في بطنها من موتى وكنوز، وتساءل الإنسان فزعًا: ما الذي حدث لها؟", "", 599, 30),
            Ayah(99, 3, "وَقَالَ ٱلْإِنسَٰنُ مَا لَهَا ۝3", "Verse 3", "إذا رُجَّت الأرض رجًّا شديدًا، وأخرجت ما في بطنها من موتى وكنوز، وتساءل الإنسان فزعًا: ما الذي حدث لها؟", "", 599, 30),
            Ayah(99, 4, "يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا ۝4", "Verse 4", "يوم القيامة تخبر الأرض بما عُمل عليها من خير أو شر، وبأن الله سبحانه وتعالى أمرها بأن تخبر بما عُمل عليها.", "", 599, 30),
            Ayah(99, 5, "بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا ۝5", "Verse 5", "يوم القيامة تخبر الأرض بما عُمل عليها من خير أو شر، وبأن الله سبحانه وتعالى أمرها بأن تخبر بما عُمل عليها.", "", 599, 30),
            Ayah(99, 6, "يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَٰلَهُمْ ۝6", "Verse 6", "يومئذ يرجع الناس عن موقف الحساب أصنافًا متفرقين؛ ليريهم الله ما عملوا من السيئات والحسنات، ويجازيهم عليها.", "", 599, 30),
            Ayah(99, 7, "فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ ۝7", "Verse 7", "فمن يعمل وزن نملة صغيرة خيرًا، ير ثوابه في الآخرة، ومن يعمل وزن نملة صغيرة شرًا، ير عقابه في الآخرة.", "", 599, 30),
            Ayah(99, 8, "وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ ۝8", "Verse 8", "فمن يعمل وزن نملة صغيرة خيرًا، ير ثوابه في الآخرة، ومن يعمل وزن نملة صغيرة شرًا، ير عقابه في الآخرة.", "", 599, 30),
        ),
        // Surah 100
        100 to listOf(
            Ayah(100, 1, "وَٱلْعَٰدِيَٰتِ ضَبْحًۭا ۝1", "Verse 1", "أقسم الله تعالى بالخيل الجاريات في سبيله نحو العدوِّ، حين يظهر صوتها من سرعة عَدْوِها. ولا يجوز للمخلوق أن يقسم إلا بالله، فإن القسم بغير الله شرك.", "", 599, 30),
            Ayah(100, 2, "فَٱلْمُورِيَٰتِ قَدْحًۭا ۝2", "Verse 2", "فالخيل اللاتي تنقدح النار من صلابة حوافرها؛ من شدَّة عَدْوها.", "", 599, 30),
            Ayah(100, 3, "فَٱلْمُغِيرَٰتِ صُبْحًۭا ۝3", "Verse 3", "فالمغيرات على الأعداء عند الصبح.", "", 599, 30),
            Ayah(100, 4, "فَأَثَرْنَ بِهِۦ نَقْعًۭا ۝4", "Verse 4", "فهيَّجْنَ بهذا العَدْو غبارًا.", "", 599, 30),
            Ayah(100, 5, "فَوَسَطْنَ بِهِۦ جَمْعًا ۝5", "Verse 5", "فتوسَّطن بركبانهن جموع الأعداء.", "", 599, 30),
            Ayah(100, 6, "إِنَّ ٱلْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌۭ ۝6", "Verse 6", "إن الإنسان لِنعم ربه لَجحود، وإنه بجحوده ذلك لمقر. وإنه لحب المال لشديد.", "", 599, 30),
            Ayah(100, 7, "وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌۭ ۝7", "Verse 7", "إن الإنسان لِنعم ربه لَجحود، وإنه بجحوده ذلك لمقر. وإنه لحب المال لشديد.", "", 599, 30),
            Ayah(100, 8, "وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ ۝8", "Verse 8", "إن الإنسان لِنعم ربه لَجحود، وإنه بجحوده ذلك لمقر. وإنه لحب المال لشديد.", "", 599, 30),
            Ayah(100, 9, "۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ ۝9", "Verse 9", "أفلا يعلم الإنسان ما ينتظره إذا أخرج الله الأموات من القبور للحساب والجزاء؟", "", 599, 30),
            Ayah(100, 10, "وَحُصِّلَ مَا فِى ٱلصُّدُورِ ۝10", "Verse 10", "واستُخرج ما استتر في الصدور من خير أو شر.", "", 600, 30),
            Ayah(100, 11, "إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍۢ لَّخَبِيرٌۢ ۝11", "Verse 11", "إن ربهم بهم وبأعمالهم يومئذ لخبير، لا يخفى عليه شيء من ذلك.", "", 600, 30),
        ),
        // Surah 101
        101 to listOf(
            Ayah(101, 1, "ٱلْقَارِعَةُ ۝1", "Verse 1", "الساعة التي تقرع قلوب الناس بأهوالها.", "", 600, 30),
            Ayah(101, 2, "مَا ٱلْقَارِعَةُ ۝2", "Verse 2", "أيُّ شيء هذه القارعة؟", "", 600, 30),
            Ayah(101, 3, "وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ ۝3", "Verse 3", "وأيُّ شيء أعلمك بها؟", "", 600, 30),
            Ayah(101, 4, "يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ ۝4", "Verse 4", "في ذلك اليوم يكون الناس في كثرتهم وتفرقهم وحركتهم كالفراش المنتشر، وهو الذي يتساقط في النار.", "", 600, 30),
            Ayah(101, 5, "وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ ۝5", "Verse 5", "وتكون الجبال كالصوف متعدد الألوان الذي يُنْفَش باليد، فيصير هباء ويزول.", "", 600, 30),
            Ayah(101, 6, "فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ ۝6", "Verse 6", "فأما من رجحت موازين حسناته، فهو في حياة مرضية في الجنة.", "", 600, 30),
            Ayah(101, 7, "فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ ۝7", "Verse 7", "فأما من رجحت موازين حسناته، فهو في حياة مرضية في الجنة.", "", 600, 30),
            Ayah(101, 8, "وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ ۝8", "Verse 8", "وأما من خفت موازين حسناته، ورجحت موازين سيئاته، فمأواه جهنم.", "", 600, 30),
            Ayah(101, 9, "فَأُمُّهُۥ هَاوِيَةٌۭ ۝9", "Verse 9", "وأما من خفت موازين حسناته، ورجحت موازين سيئاته، فمأواه جهنم.", "", 600, 30),
            Ayah(101, 10, "وَمَآ أَدْرَىٰكَ مَا هِيَهْ ۝10", "Verse 10", "وما أدراك -أيها الرسول- ما هذه الهاوية؟", "", 600, 30),
            Ayah(101, 11, "نَارٌ حَامِيَةٌۢ ۝11", "Verse 11", "إنها نار قد حَمِيت من الوقود عليها.", "", 600, 30),
        ),
        // Surah 102
        102 to listOf(
            Ayah(102, 1, "أَلْهَىٰكُمُ ٱلتَّكَاثُرُ ۝1", "Verse 1", "شغلكم عن طاعة الله التفاخر بكثرة الأموال والأولاد.", "", 600, 30),
            Ayah(102, 2, "حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ ۝2", "Verse 2", "واستمر اشتغالكم بذلك إلى أن صرتم إلى المقابر، ودُفنتم فيها.", "", 600, 30),
            Ayah(102, 3, "كَلَّا سَوْفَ تَعْلَمُونَ ۝3", "Verse 3", "ما هكذا ينبغي أن يُلْهيكم التكاثر بالأموال، سوف تتبيَّنون أن الدار الآخرة خير لكم.", "", 600, 30),
            Ayah(102, 4, "ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ ۝4", "Verse 4", "ثم احذروا سوف تعلمون سوء عاقبة انشغالكم عنها.", "", 600, 30),
            Ayah(102, 5, "كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ ۝5", "Verse 5", "ما هكذا ينبغي أن يلهيكم التكاثر بالأموال، لو تعلمون حق العلم لانزجرتم، ولبادرتم إلى إنقاذ أنفسكم من الهلاك. لتبصرُنَّ الجحيم، ثم لتبصرُنَّها دون ريب، ثم لتسألُنَّ يوم القيامة عن كل أنواع النعيم.", "", 600, 30),
            Ayah(102, 6, "لَتَرَوُنَّ ٱلْجَحِيمَ ۝6", "Verse 6", "ما هكذا ينبغي أن يلهيكم التكاثر بالأموال، لو تعلمون حق العلم لانزجرتم، ولبادرتم إلى إنقاذ أنفسكم من الهلاك. لتبصرُنَّ الجحيم، ثم لتبصرُنَّها دون ريب، ثم لتسألُنَّ يوم القيامة عن كل أنواع النعيم.", "", 600, 30),
            Ayah(102, 7, "ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ ۝7", "Verse 7", "ما هكذا ينبغي أن يلهيكم التكاثر بالأموال، لو تعلمون حق العلم لانزجرتم، ولبادرتم إلى إنقاذ أنفسكم من الهلاك. لتبصرُنَّ الجحيم، ثم لتبصرُنَّها دون ريب، ثم لتسألُنَّ يوم القيامة عن كل أنواع النعيم.", "", 600, 30),
            Ayah(102, 8, "ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ ۝8", "Verse 8", "ما هكذا ينبغي أن يلهيكم التكاثر بالأموال، لو تعلمون حق العلم لانزجرتم، ولبادرتم إلى إنقاذ أنفسكم من الهلاك. لتبصرُنَّ الجحيم، ثم لتبصرُنَّها دون ريب، ثم لتسألُنَّ يوم القيامة عن كل أنواع النعيم.", "", 600, 30),
        ),
        // Surah 103
        103 to listOf(
            Ayah(103, 1, "وَٱلْعَصْرِ ۝1", "Verse 1", "أقسم الله بالدهر على أن بني آدم لفي هلكة ونقصان. ولا يجوز للعبد أن يقسم إلا بالله، فإن القسم بغير الله شرك.", "", 601, 30),
            Ayah(103, 2, "إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ ۝2", "Verse 2", "أقسم الله بالدهر على أن بني آدم لفي هلكة ونقصان. ولا يجوز للعبد أن يقسم إلا بالله، فإن القسم بغير الله شرك.", "", 601, 30),
            Ayah(103, 3, "إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ ۝3", "Verse 3", "إلا الذين آمنوا بالله وعملوا عملا صالحًا، وأوصى بعضهم بعضًا بالاستمساك بالحق، والعمل بطاعة الله، والصبر على ذلك.", "", 601, 30),
        ),
        // Surah 104
        104 to listOf(
            Ayah(104, 1, "وَيْلٌۭ لِّكُلِّ هُمَزَةٍۢ لُّمَزَةٍ ۝1", "Verse 1", "شر وهلاك لكل مغتاب للناس، طعان فيهم.", "", 601, 30),
            Ayah(104, 2, "ٱلَّذِى جَمَعَ مَالًۭا وَعَدَّدَهُۥ ۝2", "Verse 2", "الذي كان همُّه جمع المال وتعداده.", "", 601, 30),
            Ayah(104, 3, "يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ ۝3", "Verse 3", "يظن أنه ضَمِنَ لنفسه بهذا المال الذي جمعه، الخلود في الدنيا والإفلات من الحساب.", "", 601, 30),
            Ayah(104, 4, "كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ ۝4", "Verse 4", "ليس الأمر كما ظن، ليُطرحنَّ في النار التي تهشم كل ما يُلْقى فيها.", "", 601, 30),
            Ayah(104, 5, "وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ ۝5", "Verse 5", "وما أدراك -أيها الرسول- ما حقيقة النار؟", "", 601, 30),
            Ayah(104, 6, "نَارُ ٱللَّهِ ٱلْمُوقَدَةُ ۝6", "Verse 6", "إنها نار الله الموقدة التي من شدتها تنفُذ من الأجسام إلى القلوب.", "", 601, 30),
            Ayah(104, 7, "ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ ۝7", "Verse 7", "إنها نار الله الموقدة التي من شدتها تنفُذ من الأجسام إلى القلوب.", "", 601, 30),
            Ayah(104, 8, "إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌۭ ۝8", "Verse 8", "إنها عليهم مطبَقة في سلاسل وأغلال مطوَّلة؛ لئلا يخرجوا منها.", "", 601, 30),
            Ayah(104, 9, "فِى عَمَدٍۢ مُّمَدَّدَةٍۭ ۝9", "Verse 9", "إنها عليهم مطبَقة في سلاسل وأغلال مطوَّلة؛ لئلا يخرجوا منها.", "", 601, 30),
        ),
        // Surah 105
        105 to listOf(
            Ayah(105, 1, "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ ۝1", "Verse 1", "ألم تعلم -أيها الرسول- كيف فعل ربك بأصحاب الفيل: أبرهة الحبشي وجيشه الذين أرادوا تدمير الكعبة المباركة؟", "", 601, 30),
            Ayah(105, 2, "أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍۢ ۝2", "Verse 2", "ألم يجعل ما دبَّروه من شر في إبطال وتضييع؟", "", 601, 30),
            Ayah(105, 3, "وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ ۝3", "Verse 3", "وبعث عليهم طيرًا في جماعات متتابعة، تقذفهم بحجارة من طين متحجِّر.", "", 601, 30),
            Ayah(105, 4, "تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ ۝4", "Verse 4", "وبعث عليهم طيرًا في جماعات متتابعة، تقذفهم بحجارة من طين متحجِّر.", "", 601, 30),
            Ayah(105, 5, "فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ ۝5", "Verse 5", "فجعلهم به محطمين كأوراق الزرع اليابسة التي أكلتها البهائم ثم رمت بها.", "", 601, 30),
        ),
        // Surah 106
        106 to listOf(
            Ayah(106, 1, "لِإِيلَٰفِ قُرَيْشٍ ۝1", "Verse 1", "اعْجَبوا لإلف قريش، وأمنهم، واستقامة مصالحهم، وانتظام رحلتيهم في الشتاء إلى \"اليمن\"، وفي الصيف إلى \"الشام\"، وتيسير ذلك؛ لجلب ما يحتاجون إليه.", "", 602, 30),
            Ayah(106, 2, "إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ ۝2", "Verse 2", "اعْجَبوا لإلف قريش، وأمنهم، واستقامة مصالحهم، وانتظام رحلتيهم في الشتاء إلى \"اليمن\"، وفي الصيف إلى \"الشام\"، وتيسير ذلك؛ لجلب ما يحتاجون إليه.", "", 602, 30),
            Ayah(106, 3, "فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ ۝3", "Verse 3", "فليشكروا، وليعبدوا رب هذا البيت -وهو الكعبة- الذي شرفوا به، وليوحدوه ويخلصوا له العبادة.", "", 602, 30),
            Ayah(106, 4, "ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ ۝4", "Verse 4", "الذي أطعمهم من جوع شديد، وآمنهم من فزع وخوف عظيم.", "", 602, 30),
        ),
        // Surah 107
        107 to listOf(
            Ayah(107, 1, "أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ ۝1", "Verse 1", "أرأيت حال ذلك الذي يكذِّب بالبعث والجزاء؟", "", 602, 30),
            Ayah(107, 2, "فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ ۝2", "Verse 2", "فذلك الذي يدفع اليتيم بعنف وشدة عن حقه؛ لقساوة قلبه.", "", 602, 30),
            Ayah(107, 3, "وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ ۝3", "Verse 3", "ولا يحضُّ غيره على إطعام المسكين، فكيف له أن يطعمه بنفسه؟", "", 602, 30),
            Ayah(107, 4, "فَوَيْلٌۭ لِّلْمُصَلِّينَ ۝4", "Verse 4", "فعذاب شديد للمصلين الذين هم عن صلاتهم لاهون، لا يقيمونها على وجهها، ولا يؤدونها في وقتها.", "", 602, 30),
            Ayah(107, 5, "ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ ۝5", "Verse 5", "فعذاب شديد للمصلين الذين هم عن صلاتهم لاهون، لا يقيمونها على وجهها، ولا يؤدونها في وقتها.", "", 602, 30),
            Ayah(107, 6, "ٱلَّذِينَ هُمْ يُرَآءُونَ ۝6", "Verse 6", "الذين هم يتظاهرون بأعمال الخير مراءاة للناس.", "", 602, 30),
            Ayah(107, 7, "وَيَمْنَعُونَ ٱلْمَاعُونَ ۝7", "Verse 7", "ويمنعون إعارة ما لا تضر إعارته من الآنية وغيرها، فلا هم أحسنوا عبادة ربهم، ولا هم أحسنوا إلى خلقه.", "", 602, 30),
        ),
        // Surah 108
        108 to listOf(
            Ayah(108, 1, "إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ ۝1", "Verse 1", "إنا أعطيناك -أيها النبي- الخير الكثير في الدنيا والآخرة، ومن ذلك نهر الكوثر في الجنة الذي حافتاه خيام اللؤلؤ المجوَّف، وطينه المسك.", "", 602, 30),
            Ayah(108, 2, "فَصَلِّ لِرَبِّكَ وَٱنْحَرْ ۝2", "Verse 2", "فأخلص لربك صلاتك كلها، واذبح ذبيحتك له وعلى اسمه وحده.", "", 602, 30),
            Ayah(108, 3, "إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ ۝3", "Verse 3", "إن مبغضك ومبغض ما جئت به من الهدى والنور، هو المنقطع أثره، المقطوع من كل خير.", "", 602, 30),
        ),
        // Surah 109
        109 to listOf(
            Ayah(109, 1, "قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ ۝1", "Verse 1", "قل -أيها الرسول- للذين كفروا بالله ورسوله: يا أيها الكافرون بالله.", "", 603, 30),
            Ayah(109, 2, "لَآ أَعْبُدُ مَا تَعْبُدُونَ ۝2", "Verse 2", "لا أعبد ما تعبدون من الأصنام والآلهة الزائفة.", "", 603, 30),
            Ayah(109, 3, "وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ ۝3", "Verse 3", "ولا أنتم عابدون ما أعبد من إله واحد، هو الله رب العالمين المستحق وحده للعبادة.", "", 603, 30),
            Ayah(109, 4, "وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ ۝4", "Verse 4", "ولا أنا عابد ما عبدتم من الأصنام والآلهة الباطلة.", "", 603, 30),
            Ayah(109, 5, "وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ ۝5", "Verse 5", "ولا أنتم عابدون مستقبلا ما أعبد. وهذه الآية نزلت في أشخاص بأعيانهم من المشركين، قد علم الله أنهم لا يؤمنون أبدًا.", "", 603, 30),
            Ayah(109, 6, "لَكُمْ دِينُكُمْ وَلِىَ دِينِ ۝6", "Verse 6", "لكم دينكم الذي أصررتم على اتباعه، ولي ديني الذي لا أبغي غيره.", "", 603, 30),
        ),
        // Surah 110
        110 to listOf(
            Ayah(110, 1, "إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ ۝1", "Verse 1", "إذا تمَّ لك -أيها الرسول- النصر على كفار قريش، وتم لك فتح \"مكة\".", "", 603, 30),
            Ayah(110, 2, "وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا ۝2", "Verse 2", "ورأيت الكثير من الناس يدخلون في الإسلام جماعات جماعات.", "", 603, 30),
            Ayah(110, 3, "فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا ۝3", "Verse 3", "إذا وقع ذلك فتهيأ للقاء ربك بالإكثار من التسبيح بحمده والإكثار من استغفاره، إنه كان توابًا على المسبحين والمستغفرين، يتوب عليهم ويرحمهم ويقبل توبتهم.", "", 603, 30),
        ),
        // Surah 111
        111 to listOf(
            Ayah(111, 1, "تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ ۝1", "Verse 1", "خسرت يدا أبي لهب وشقي بإيذائه رسول الله محمدا صلى الله عليه وسلم، وقد تحقق خسران أبي لهب.", "", 603, 30),
            Ayah(111, 2, "مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ ۝2", "Verse 2", "ما أغنى عنه ماله وولده، فلن يَرُدَّا عنه شيئًا من عذاب الله إذا نزل به.", "", 603, 30),
            Ayah(111, 3, "سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ ۝3", "Verse 3", "سيدخل نارًا متأججة، هو وامرأته التي كانت تحمل الشوك، فتطرحه في طريق النبي صلى الله عليه وسلم؛ لأذيَّته.", "", 603, 30),
            Ayah(111, 4, "وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ ۝4", "Verse 4", "سيدخل نارًا متأججة، هو وامرأته التي كانت تحمل الشوك، فتطرحه في طريق النبي صلى الله عليه وسلم؛ لأذيَّته.", "", 603, 30),
            Ayah(111, 5, "فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ ۝5", "Verse 5", "في عنقها حبل محكم الفَتْلِ مِن ليف شديد خشن، تُرْفَع به في نار جهنم، ثم تُرْمى إلى أسفلها.", "", 603, 30),
        ),
        // Surah 112
        112 to listOf(
            Ayah(112, 1, "قُلْ هُوَ ٱللَّهُ أَحَدٌ ۝1", "Verse 1", "قل -أيها الرسول-: هو الله المتفرد بالألوهية والربوبية والأسماء والصفات، لا يشاركه أحد فيها.", "", 604, 30),
            Ayah(112, 2, "ٱللَّهُ ٱلصَّمَدُ ۝2", "Verse 2", "الله وحده المقصود في قضاء الحوائج والرغائب.", "", 604, 30),
            Ayah(112, 3, "لَمْ يَلِدْ وَلَمْ يُولَدْ ۝3", "Verse 3", "ليس له ولد ولا والد ولا صاحبة.", "", 604, 30),
            Ayah(112, 4, "وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ ۝4", "Verse 4", "ولم يكن له مماثلا ولا مشابهًا أحد من خلقه، لا في أسمائه ولا في صفاته، ولا في أفعاله، تبارك وتعالى وتقدَّس.", "", 604, 30),
        ),
        // Surah 113
        113 to listOf(
            Ayah(113, 1, "قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ ۝1", "Verse 1", "قل -أيها الرسول-: أعوذ وأعتصم برب الفلق، وهو الصبح.", "", 604, 30),
            Ayah(113, 2, "مِن شَرِّ مَا خَلَقَ ۝2", "Verse 2", "من شر جميع المخلوقات وأذاها.", "", 604, 30),
            Ayah(113, 3, "وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝3", "Verse 3", "ومن شر ليل شديد الظلمة إذا دخل وتغلغل، وما فيه من الشرور والمؤذيات.", "", 604, 30),
            Ayah(113, 4, "وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ ۝4", "Verse 4", "ومن شر الساحرات اللاتي ينفخن فيما يعقدن من عُقَد بقصد السحر.", "", 604, 30),
            Ayah(113, 5, "وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ۝5", "Verse 5", "ومن شر حاسد مبغض للناس إذا حسدهم على ما وهبهم الله من نعم، وأراد زوالها عنهم، وإيقاع الأذى بهم.", "", 604, 30),
        ),
        // Surah 114
        114 to listOf(
            Ayah(114, 1, "قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ ۝1", "Verse 1", "قل -أيها الرسول-: أعوذ وأعتصم برب الناس، القادر وحده على ردِّ شر الوسواس.", "", 604, 30),
            Ayah(114, 2, "مَلِكِ ٱلنَّاسِ ۝2", "Verse 2", "ملك الناس المتصرف في كل شؤونهم، الغنيِّ عنهم.", "", 604, 30),
            Ayah(114, 3, "إِلَٰهِ ٱلنَّاسِ ۝3", "Verse 3", "إله الناس الذي لا معبود بحق سواه.", "", 604, 30),
            Ayah(114, 4, "مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ۝4", "Verse 4", "من أذى الشيطان الذي يوسوس عند الغفلة، ويختفي عند ذكر الله.", "", 604, 30),
            Ayah(114, 5, "ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ ۝5", "Verse 5", "الذي يبثُّ الشر والشكوك في صدور الناس.", "", 604, 30),
            Ayah(114, 6, "مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ ۝6", "Verse 6", "من شياطين الجن والإنس.", "", 604, 30),
        ),
    )
}
